lid white;background:var(--c);box-shadow:0 0 0 1px #ddd;cursor:pointer}.swatch.active{box-shadow:0 0 0 2px var(--purple)}.divider{width:1px;height:32px;background:#eee;margin:0 13px}.size{width:34px;height:34px;border:0;border-radius:8px;background:transparent;display:grid;place-items:center;cursor:pointer}.size i{display:block;border-radius:50%;background:#555}.size.active{background:#efedff}.tool-spacer{flex:1}.tool-btn{width:38px;height:38px;border:0;background:#f5f4f7;border-radius:9px;margin-left:7px;font-size:18px;cursor:pointer}.chat{display:flex;flex-direction:column}.messages{flex:1;padding:10px 12px;overflow:auto}.system-msg{background:#f5f3ff;border-radius:8px;padding:9px;font-size:10px;color:#777;margin-bottom:8px}.system-msg b{display:block;color:var(--purple);margin-top:3px}.message{display:flex;gap:7px;margin:8px 0;font-size:11px}.message-avatar{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;color:white;font-size:8px;font-weight:900}.message b{display:block;font-size:10px}.message.correct{background:#eaffee;border-radius:8px;padding:7px;color:#2d9250}.guess-form{height:62px;border-top:1px solid var(--line);display:flex;padding:9px}.guess-form input{min-width:0;flex:1;border:1px solid #e6e4e9;border-radius:9px 0 0 9px;padding:0 10px;outline:none;font-size:12px}.guess-form input:focus{border-color:#aaa2f5}.guess-form button{width:42px;border:0;border-radius:0 9px 9px 0;background:var(--purple);color:white;cursor:pointer}.round-result{position:absolute;inset:0;background:rgba(245,244,240,.72);backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center}.round-result.show{display:flex}.result-card{text-align:center;background:white;border-radius:20px;padding:28px 44px;box-shadow:0 18px 50px rgba(38,39,44,.15)}.result-card>span{font-size:38px}.result-card h2{margin:8px 0 4px}.result-card p{font-size:12px;color:#777}.result-card button,.primary-btn{border:0;border-radius:10px;background:var(--purple);color:white;height:42px;padding:0 22px;font-weight:800;cursor:pointer}.modal{position:absolute;z-index:20;inset:0;background:rgba(28,29,33,.34);display:none;align-items:center;justify-content:center}.modal.show{display:flex}.modal-card{position:relative;width:min(420px,calc(100% - 30px));background:white;border-radius:22px;text-align:center;padding:28px}.modal-close{position:absolute;right:14px;top:12px;border:0;background:#f5f4f7;border-radius:50%;width:32px;height:32px;cursor:pointer}.modal-icon{width:58px;height:58px;border-radius:18px;background:#eeecff;display:grid;place-items:center;margin:auto;font-size:28px}.modal-card h2{margin:12px 0 6px}.modal-card>p{color:#777;font-size:13px}.tips{text-align:left;margin:20px 0}.tips>div{display:flex;align-items:center;gap:10px;margin:9px 0}.tips>div>b{width:32px;height:32px;border-radius:50%;background:#f1efff;color:var(--purple);display:grid;place-items:center}.tips span{display:flex;flex-direction:column;font-size:12px}.tips small{color:#999;margin-top:3px}.primary-btn{width:100%}
