const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const port=process.env.APP_PORT||3000;
const words=['apple','rocket','guitar','pizza','castle','penguin','rainbow','camera','banana','turtle','cactus','bicycle','snowman','sailboat','butterfly'];
const rooms=new Map();
const mime={'.html':'text/html','.css':'text/css','.js':'application/javascript','.jpg':'image/jpeg','.png':'image/png','.svg':'image/svg+xml'};
function rand(n=6){return crypto.randomBytes(n).toString('hex').slice(0,n).toUpperCase()};
function body(req){return new Promise(r=>{let s='';req.on('data',d=>s+=d);req.on('end',()=>{try{r(JSON.parse(s||'{}'))}catch(e){r({})}})})}
function send(res,x,status=200){res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(x))}
function publicState(room,token){const me=room.players.find(p=>p.token===token);const drawer=room.players[room.drawer];const answer=me&&me.id===drawer?.id;return {code:room.code,started:room.started,round:room.round,status:room.status,roundEnds:room.roundEnds,drawer:drawer&&{id:drawer.id,name:drawer.name},me:me&&{id:me.id,name:me.name,score:me.score,host:me.id===room.host},players:room.players.map(p=>({id:p.id,name:p.name,score:p.score,guessed:p.guessed})),word:(answer||room.status==='ended'?room.word:room.word.split('').map(c=>c===' '?' ':'_').join(' ')),strokes:room.strokes,messages:room.messages.slice(-40),host:room.host}}
function makeRoom(host){const code=rand(6);const room={code,host:host.id,players:[host],started:false,round:0,status:'lobby',drawer:0,word:'',strokes:[],messages:[],roundEnds:0};rooms.set(code,room);return room}
function nextRound(room){if(!room.started)return;room.round++;if(room.round>5){room.status='ended';room.messages.push({system:true,text:'Game complete!'});return}room.drawer=(room.drawer+1)%room.players.length;room.word=words[(room.round*3+room.drawer)%words.length];room.status='playing';room.strokes=[];room.roundEnds=Date.now()+60000;room.players.forEach(p=>p.guessed=false);room.messages.push({system:true,text:`${room.players[room.drawer].name} is drawing!`})}
function tick(){for(const room of rooms.values()){if(room.started&&room.status==='playing'&&Date.now()>room.roundEnds){room.status='roundEnd';room.messages.push({system:true,text:`Time! The word was ${room.word}`}}}}
setInterval(tick,500);
const server=http.createServer(async(req,res)=>{const u=new URL(req.url,'http://localhost:'+port);
 try{
  if(u.pathname==='/' )u.pathname='/index.html';
  if(u.pathname.startsWith('/api/')){const b=await body(req);if(req.method==='POST'&&u.pathname===' /api/create'.trim()){} }
 }catch(e){ }
 if(u.pathname.startsWith('/api/')){let b=await body(req);
  if(req.method==='POST'&&u.pathname===' /api/create'.trim()){} 
  if(req.method==='POST'&&u.pathname==='/api/create'){const name=(b.name||'Player').trim().slice(0,16)||'Player';const p={id:rand(8),token:rand(16),name,score:0,guessed:false};const room=makeRoom(p);return send(res,{token:p.token,code:room.code})}
  if(req.method==='POST'&&u.pathname==='/api/join'){const code=(b.code||'').trim().toUpperCase();const room=rooms.get(code);if(!room)return send(res,{error:'Room not found'},404);if(room.started)return send(res,{error:'Game already started'},400);if(room.players.length>=6)return send(res,{error:'Room is full'},400);const p={id:rand(8),token:rand(16),name:(b.name||'Player').trim().slice(0,16)||'Player',score:0,guessed:false};room.players.push(p);room.messages.push({system:true,text:`${p.name} joined`});return send(res,{token:p.token,code})}
  const code=(b.code||u.searchParams.get('code')||'').toUpperCase(),token=b.token||u.searchParams.get('token');const room=rooms.get(code);if(!room)return send(res,{error:'Room not found'},404);const me=room.players.find(p=>p.token===token);if(!me)return send(res,{error:'Unauthorized'},401);
  if(req.method==='GET'&&u.pathname===' /api/state'.trim()){} 
  if(req.method==='GET'&&u.pathname==='/api/state')return send(res,publicState(room,token));
  if(req.method==='POST'&&u.pathname===' /api/start'.trim()){}
  if(req.method==='POST'&&u.pathname==='/api/start'){if(room.host!==me.id)return send(res,{error:'Only host can start'},403);if(room.players.length<2)return send(res,{error:'Need at least 2 players'},400);room.started=true;room.round=0;room.drawer=0;nextRound(room);return send(res,{ok:true})}
  if(req.method==='POST'&&u.pathname==='/api/draw'){const drawer=room.players[room.drawer];if(room.status==='playing'&&drawer.id===me.id&&b.stroke){room.strokes.push(b.stroke);if(room.strokes.length>500)room.strokes.shift()}return send(res,{ok:true})}
  if(req.method==='POST'&&u.pathname==='/api/clear'){const drawer=room.players[room.drawer];if(drawer.id===me.id)room.strokes=[];return send(res,{ok:true})}
  if(req.method==='POST'&&u.pathname==='/api/undo'){const drawer=room.players[room.drawer];if(drawer.id===me.id)room.strokes.pop();return send(res,{ok:true})}
  if(req.method==='POST'&&u.pathname==='/api/guess'){if(room.status!=='playing'||me.guessed)return send(res,{ok:true});const guess=(b.text||'').trim().slice(0,24);if(!guess)return send(res,{ok:true});const drawer=room.players[room.drawer];const correct=guess.toLowerCase()===room.word.toLowerCase();room.messages.push({name:me.name,text:correct?'Guessed the word!':guess,correct,id:me.id});if(correct&&drawer.id!==me.id){me.guessed=true;me.score+=Math.max(20,Math.ceil((room.roundEnds-Date.now())/300));if(Date.now()%2===0){} }return send(res,{ok:true})}
  if(req.method==='POST'&&u.pathname==='/api/next'){if(room.host!==me.id)return send(res,{error:'Only host can continue'},403);nextRound(room);return send(res,{ok:true})}
  return send(res,{error:'Unknown API'},404);
 }
 const file=path.join(process.cwd(),u.pathname==='/'?'index.html':u.pathname.slice(1));if(!file.startsWith(process.cwd()))return res.writeHead(403).end();fs.readFile(file,(e,d)=>{if(e){res.writeHead(404);return res.end('Not found')}res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});res.end(d)});
});server.listen(port,'0.0.0.0',()=>console.log('Scribble server on '+port));

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#board'),ctx=canvas.getContext('2d');
let token='',code='',state=null,color='#25272c',size=5,drawing=false,current=[],lastState='',pollId;

function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=r.width*dpr;canvas.height=r.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);redraw()}
function redraw(){const r=canvas.getBoundingClientRect();ctx.fillStyle='#fff';ctx.fillRect(0,0,r.width,r.height);ctx.lineCap='round';ctx.lineJoin='round';if(state?.strokes)for(const s of state.strokes){if(!s.points||s.points.length<2)continue;ctx.strokeStyle=s.color;ctx.lineWidth=s.size;ctx.beginPath();ctx.moveTo(s.points[0].x,s.points[0].y);for(let i=1;i<s.points.length;i++)ctx.lineTo(s.points[i].x,s.points[i].y);ctx.stroke()} }
function point(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
canvas.addEventListener('pointerdown',e=>{if(!canDraw())return;canvas.setPointerCapture(e.pointerId);drawing=true;current=[point(e)];api('/api/draw',{stroke:{color,size,points:current}})});
canvas.addEventListener('pointermove',e=>{if(!drawing||!canDraw())return;const p=point(e);current.push(p);const s=current.length>1?safe();function safe(){return null}ctx.strokeStyle=color;ctx.lineWidth=size;ctx.beginPath();ctx.moveTo(current[current.length-2].x,current[current.length-2].y);ctx.lineTo(p.x,p.y);ctx.stroke();if(current.length%3===0)api('/api/draw',{stroke:{color,size,points:[...current]}})});
canvas.addEventListener('pointerup',()=>{drawing=false;if(current.length){api('/api/draw',{stroke:{color,size,points:[...current]}})}});
canvas.addEventListener('pointercancel',()=>drawing=false);
function canDraw(){return state&&state.status==='playing'&&state.drawer?.id===state.me?.id}
async function api(path,data={}){const r=await fetch(path,{method:path.includes('state')?'GET':'POST',headers:{'Content-Type':'application/json'},body:path.includes('state')?undefined:JSON.stringify({...data,code,token})});return r.json()}
async function poll(){if(!token||!code)return;try{const old=state;state=await api('/api/state');render(old)}catch(e){}}
function render(old){resize();$('#roundLabel').innerHTML=`${state.started?'Round '+state.round:'Lobby'} <span>of 5</span>`;$('#playerCount').textContent=state.players.length;
 $('#players').innerHTML=state.players.map(p=>{const drawing=state.drawer?.id===p.id;return `<div class="player ${drawing?'drawing':''}"><div class="player-avatar" style="background:${p.id===state.me?.id?'#f58d70':'#6e9efa'}">${p.name[0].toUpperCase()}</div><div class="player-info"><div class="player-name">${p.name}${p.id===state.me?.id?' (You)':''}</div><div class="player-state">${drawing?'Drawing':p.guessed?'Guessed':'Thinking...'}</div></div><div class="player-score">${p.score}</div></div>`}).join('');
 $('#wordBlanks').textContent=state.word||'_ _ _ _ _';$('#timerNum').textContent=state.roundEnds?Math.max(0,Math.ceil((state.roundEnds-Date.now())/1000)):60;$('#guessCount').textContent=state.messages.filter(m=>!m.system&&!m.correct).length;
 if(state.drawer){$('#turnBanner').innerHTML=`<div class="turn-avatar">${state.drawer.name[0].toUpperCase()}</div><div><small>${canDraw()?'You are drawing':'Now drawing'}</strong></div>`.replace('<strong>','<strong>').replace('</strong>','</strong>');$('#turnBanner').innerHTML=`<div class="turn-avatar">${state.drawer.name[0].toUpperCase()}</div><div><small>${canDraw()?'You are drawing':'Now drawing'}</small><strong>${canDraw()?'Draw the secret word':state.drawer.name+' is sketching...'}</strong></div>`}
 const key=JSON.stringify(state.messages);if(key!==lastState){$('#messages').innerHTML=state.messages.map(m=>m.system?`<div class="system-msg"><b>${m.text}</b></div>`:`<div class="message ${m.correct?'correct':''}"><div class="message-avatar">${m.name[0].toUpperCase()}</div><div><b>${m.name}</b><span>${m.text}</span></div></div>`).join('');lastState=key;}
 redraw();
 if(state.status==='roundEnd'||state.status==='ended')showResult(state.status==='ended');
 else $('#roundResult').classList.remove('show');
}
function showResult(final){$('#roundResult').classList.add('show');$('#resultEmoji').textContent=final?'🏆':'⏰';$('#resultTitle').textContent=final?'Game complete!':'Time!';$('#resultCopy').innerHTML=final?'The highest score wins!':`The word was <b>${state.word}</b>`;const b=$('#nextRoundBtn');b.textContent=state.me?.host?(final?'Play again':'Next round'):'Waiting for host';b.disabled=!state.me?.host}
$('#nextRoundBtn').onclick=()=>api('/api/next');
async function enterLobby(create){const name=$('#nameInput').value.trim().slice(0,16)||'Player';const res=await fetch('/api/'+(create?'create':'join'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(create?{name}:{name,code:$('#codeInput').value.toUpper()})}).then(r=>r.json());if(res.error){$('#lobbyStatus').textContent=res.error;return}token=res.token;code=res.code;$('#lobbyModal').classList.remove('show');clearInterval(pollId);pollId=setInterval(poll,700);poll()}
$('#createBtn').onclick=()=>enterLobby(true);$('#joinBtn').onclick=()=>enterLobby(false);
$('#guessForm').onsubmit=async e=>{e.preventDefault();const i=$('#guessInput'),text=i.value.trim();if(!text)return;await api('/api/guess',{text});i.value='';poll()};
$('#undoBtn').onclick=()=>api('/api/undo');$('#clearBtn').onclick=()=>api('/api/clear');
$$('#colors .swatch').forEach(b=>b.onclick=()=>{$$('#colors .swatch').forEach(x=>x.classList.remove('active'));b.classList.add('active');color=b.dataset.color});
$$('#sizes .size').forEach(b=>b.onclick=()=>{$$('#sizes .size').forEach(x=>x.classList.remove('active'));b.classList.add('active');size=+b.dataset.size});
$('#helpBtn').onclick=()=>$('#helpModal').classList.add('show');$('#closeHelp').onclick=()=>$('#helpModal').classList.remove('show');$('#playBtn').onclick=()=>$('#helpModal').classList.remove('show');
let sound=true;$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'🔊':'🔇'};
window.addEventListener('resize',resize);

// Host can start from the lobby using the room code shown in the round title by clicking avatar.
$('#avatarBtn').onclick=async()=>{if(!token)return;if(state?.started)return;$('#lobbyStatus').textContent='Starting game...';await api('/api/start')};
setInterval(()=>{if(state?.roundEnds&&state.status==='playing')$('#timerNum').textContent=Math.max(0,Math.ceil((state.roundEnds-Date.now())/1000))},300);

